declare(strict_types=1);if(PHP_SAPI!=='cli'){http_response_code(404);exit;}require_once __DIR__.'/bootstrap.php';$projectRoot=dirname(__DIR__,4);require$projectRoot.'/.env.php';$pdo=new PDO('mysql:host='.$db['host'].';dbname='.$db['name'],$db['username'],$db['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);unset($db);foreach(['admin_bank_account','admin_bank_import','admin_bank_transaction','admin_bank_match_proposal']as$table){$statement=$pdo->prepare('SHOW TABLES LIKE :table');$statement->execute([':table'=>$table]);adminBankingAssert($statement->fetchColumn()!==false,'Schema mist '.$table.'; voer force_aw uit.');}foreach(['admin_bank_account'=>['tenant_id','public_id','account_reference','currency'],'admin_bank_import'=>['tenant_id','bank_account_public_id','checksum_sha256','imported_count'],'admin_bank_transaction'=>['tenant_id','bank_account_public_id','external_id','amount_minor','source_snapshot','status'],'admin_bank_match_proposal'=>['tenant_id','transaction_public_id','target_type','target_public_id']]as$table=>$columns){$actual=[];foreach($pdo->query('SHOW COLUMNS FROM `'.$table.'`')->fetchAll(PDO::FETCH_ASSOC)as$row){$actual[]=$row['Field'];}foreach($columns as$column){adminBankingAssert(in_array($column,$actual,true),$table.' mist kolom '.$column.'.');}}echo "AdminBanking schema tests passed.\n";
